using DocumentFormat.OpenXml.Vml;

namespace SalesSystem.Rfq.Models
{
    public class PartImageData
    {
        byte[] _ImageBytes;

        public IReadOnlyList<byte> ImageBytes
        {
            get => _ImageBytes;
            set => _ImageBytes = value?.ToArray() ?? Array.Empty<byte>();
        }

        public string? Source
        {
            get
            {
                byte[] ar = ImageBytes.ToArray();
                string? s = Convert.ToBase64String(ar);
                return s;
            }
        }

        public string MimeType
        { get; set; }

        public PartImageData()
        {
            _ImageBytes = Array.Empty<byte>();
            MimeType = "image/png";
        }
        static string NoImageSource
        {
            get
            {
                return """
                    
                    
                    """;
            }
        }
        static PartImageData _NoImage;
        static PartImageData()
        {
            _NoImage = new PartImageData();
            _NoImage.ImageBytes = Encoding.ASCII.GetBytes(NoImageSource);
        }
        public static PartImageData NoImage
        {
            get => _NoImage;
        }
    }
}
